/**
 * Akshara - translation table.
 *
 * One row per key, all six languages on that row. The layout is deliberate:
 * a missing translation is visible at a glance, so the interface can never
 * fall back to English for one stray label while the rest of the screen is
 * in Kannada. Change #5 depends on this file being complete.
 *
 * Languages: en English | hi हिंदी | kn ಕನ್ನಡ | ta தமிழ் | te తెలుగు | bn বাংলা
 */

export const LOCALES = ["en", "hi", "kn", "ta", "te", "bn"];

/**
 * Endonyms. Every language is ALWAYS written in its own script, whatever the
 * interface language currently is. This is change #4: the language switcher
 * never translates itself, so a Kannada speaker still sees हिंदी as हिंदी.
 */
export const LANGUAGE_NAMES = {
  en: "English",
  hi: "हिंदी",
  kn: "ಕನ್ನಡ",
  ta: "தமிழ்",
  te: "తెలుగు",
  bn: "বাংলা",
};

